using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Security.Cryptography;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
namespace ParkingLotEnvironment.CloudPilot {
public static class RoadMatchRunner {
 const string S="Assets/_Parkside/Scenes/ParklingLot.unity",W="Assets/ParkingLotEnvironment/CloudPilot/KRRoadMatch20261104",Trial=W+"/RoadMatch.unity",Old="Assets/ParkingLotEnvironment/CloudPilot/IntegratedRequest20261103/IntegratedFinalCandidate.unity",Expected="7939ab3c939f8769be4ed81e4d4ab0d2ed3691051592e0c0897b2c8a69075478";
 static Camera cam;static string output,hash;static int frame=-1;
 static string Hash(string p){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();}
 static void Check(){if(File.Exists("/workspaces/parkside-setup/STOP")||Hash(S)!=Expected)throw new Exception("STOP or source changed");}
 static GameObject Root(){return SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name=="ParkingLot_CornerPilot_Root");}
 static string PathOf(Transform t,Transform root){string p=t.name;while(t.parent&&t.parent!=root){t=t.parent;p=t.name+"/"+p;}return p;}
 public static void Run(){try{Check();var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,"-roadOutput");output=System.IO.Path.GetFullPath(a[i+1]);Directory.CreateDirectory(output);if(File.Exists(Trial))throw new Exception("Candidate exists");EditorSceneManager.OpenScene(S);var root=Root();var paths=root.GetComponentsInChildren<Renderer>(true).Where(r=>r.sharedMaterials.Any(m=>m&&m.shader&&m.shader.name=="ParkingLot/Realism20261104/Road")).Select(r=>PathOf(r.transform,root.transform)).ToArray();if(paths.Length==0)throw new Exception("Current road not found");cam=root.GetComponentInChildren<Camera>();Render("before.png");
  EditorSceneManager.OpenScene(Old);root=Root();var replacements=new Dictionary<string,Material[]>();var notes=new List<string>();foreach(var p in paths){var t=root.transform.Find(p);if(!t)throw new Exception("Old road missing "+p);var r=t.GetComponent<Renderer>();var mats=r.sharedMaterials.Select(m=>{var c=new Material(m){name="ReferenceRoad_"+m.name};AssetDatabase.CreateAsset(c,AssetDatabase.GenerateUniqueAssetPath(W+"/"+c.name+".mat"));notes.Add(p+": "+m.name+" shader="+m.shader.name);return c;}).ToArray();replacements[p]=mats;}
  EditorSceneManager.OpenScene(S);root=Root();var lighting=AssetDatabase.GetAssetPath(Lightmapping.lightingDataAsset);foreach(var entry in replacements){var r=root.transform.Find(entry.Key).GetComponent<Renderer>();r.sharedMaterials=entry.Value;EditorUtility.SetDirty(r);}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());if(!EditorSceneManager.SaveScene(SceneManager.GetActiveScene(),Trial))throw new Exception("Save failed");hash=Hash(Trial);EditorSceneManager.OpenScene(Trial);if(AssetDatabase.GetAssetPath(Lightmapping.lightingDataAsset)!=lighting)throw new Exception("Lighting changed");cam=Root().GetComponentInChildren<Camera>();cam.enabled=false;File.WriteAllLines(output+"/changes.txt",notes);EditorApplication.update+=Tick;
 }catch(Exception e){Fail(e);}}
 static void Tick(){try{Check();if(frame<0)Render(null);else if(frame==0)Render("eye.png");else{EditorApplication.update-=Tick;if(Hash(Trial)!=hash)throw new Exception("Candidate changed");File.WriteAllText(output+"/complete.txt","Only asphalt renderer material references replaced. Camera, geometry, lights, baked lightmaps, probes unchanged. Candidate SHA="+hash);EditorApplication.Exit(0);return;}frame++;}catch(Exception e){Fail(e);}}
 static void Render(string name){var rt=new RenderTexture(1920,1080,24,RenderTextureFormat.ARGBHalf);var pic=new Texture2D(1920,1080,TextureFormat.RGB24,false);var prev=RenderTexture.active;var old=cam.targetTexture;try{rt.Create();cam.targetTexture=rt;cam.Render();if(name!=null){RenderTexture.active=rt;pic.ReadPixels(new Rect(0,0,1920,1080),0,0);pic.Apply();File.WriteAllBytes(output+"/"+name,pic.EncodeToPNG());}}finally{cam.targetTexture=old;RenderTexture.active=prev;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(pic);}}
 static void Fail(Exception e){EditorApplication.update-=Tick;Debug.LogException(e);if(output!=null)File.WriteAllText(output+"/FAILED.txt",e.ToString());EditorApplication.Exit(1);}
}}
